import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"Space Membership System","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/space-membership.md","filePath":"architecture/space-membership.md","lastUpdated":1780254295000}'),r={name:"architecture/space-membership.md"};function s(n,e,l,c,d,p){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="space-membership-system" tabindex="-1">Space Membership System <a class="header-anchor" href="#space-membership-system" aria-label="Permalink to &quot;Space Membership System&quot;">​</a></h1><p>Spaces are secure collaboration units. Access is governed by explicit capabilities so only authorized peers can read or publish space content. This document explains the main artifacts and how a join is processed end-to-end.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="joinrequest" tabindex="-1">JoinRequest <a class="header-anchor" href="#joinrequest" aria-label="Permalink to &quot;JoinRequest&quot;">​</a></h3><ul><li>Created by a user&#39;s Soma daemon when they attempt to join a space.</li><li>Contains the requester&#39;s Peer ID, target space identifier, and any invite metadata.</li><li>Delivered over the current libp2p request/response join flow to a known target peer or decider.</li></ul><h3 id="membershipcapability" tabindex="-1">MembershipCapability <a class="header-anchor" href="#membershipcapability" aria-label="Permalink to &quot;MembershipCapability&quot;">​</a></h3><ul><li>The signed credential proving that a peer belongs to a space.</li><li>Stored inside the requesting daemon once issued so membership survives restarts.</li><li>Encodes the granted membership for the requesting peer and may carry role information.</li></ul><h3 id="human-facing-roles" tabindex="-1">Human-facing roles <a class="header-anchor" href="#human-facing-roles" aria-label="Permalink to &quot;Human-facing roles&quot;">​</a></h3><ul><li><code>Owner</code> - full workspace control, including access and settings.</li><li><code>Editor</code> - can create and edit workspace content.</li><li><code>Viewer</code> - can open and read content, but should not edit.</li><li><code>Member</code> - general workspace access when you do not want a more specific role yet.</li><li><code>Bot</code> - non-human peer used for approved automation, caching, or indexing. Join approval authority is separate and must be delegated explicitly.</li></ul><h3 id="bot-action-categories" tabindex="-1">Bot action categories <a class="header-anchor" href="#bot-action-categories" aria-label="Permalink to &quot;Bot action categories&quot;">​</a></h3><ul><li><code>cache and serve</code> - fetch, verify, cache, and serve allowed content.</li><li><code>organize and index</code> - classify, extract metadata, or prepare search/index views.</li><li><code>automation and script execution</code> - run approved workflows or scripts.</li></ul><p>These categories are not implied just by assigning the <code>Bot</code> role. They must be granted intentionally for that space.</p><h3 id="issuercapability" tabindex="-1">IssuerCapability <a class="header-anchor" href="#issuercapability" aria-label="Permalink to &quot;IssuerCapability&quot;">​</a></h3><ul><li>Grants authority to create MembershipCapabilities for a space.</li><li>Issued by the space owner to a delegate peer through <code>Daemon/IssueIssuerCapability</code> or admin tooling.</li><li>Stored as an owner-signed artifact and checked for space, delegate, role, and expiry before it can mint membership.</li></ul><h3 id="spacegenesisartifact" tabindex="-1">SpaceGenesisArtifact <a class="header-anchor" href="#spacegenesisartifact" aria-label="Permalink to &quot;SpaceGenesisArtifact&quot;">​</a></h3><ul><li>Owner-signed proof for the initial space record.</li><li>Created by the daemon during <code>CreateSpace</code> and stored beside the local <code>spaces</code> row.</li><li>Lets peers verify that <code>owner_peer_id</code> is not only DB-local metadata.</li></ul><h3 id="bot-onboarding" tabindex="-1">Bot Onboarding <a class="header-anchor" href="#bot-onboarding" aria-label="Permalink to &quot;Bot Onboarding&quot;">​</a></h3><ul><li>Bots receive join requests over the current join protocol, evaluate policy, and issue MembershipCapabilities when authorized.</li><li>Delivery can happen immediately over the join decision path or later through the mailbox/outbox retry path.</li><li>Bots may still trigger follow-up automation, but the core implemented responsibility is join decisioning and related persistence.</li></ul><h2 id="join-flow" tabindex="-1">Join Flow <a class="header-anchor" href="#join-flow" aria-label="Permalink to &quot;Join Flow&quot;">​</a></h2><ol><li><strong>JoinRequest sent</strong> – the Soma desktop app asks the local daemon to join a space; the daemon sends a JoinRequest over libp2p.</li><li><strong>Request processed</strong> – the space bot or owner/issuer peer receives the request, verifies policy, and checks IssuerCapability permissions.</li><li><strong>Membership granted</strong> – A MembershipCapability is created, typically by signing a statement <code>Peer X is a member of Space Y</code> with the issuer’s key.</li><li><strong>Delivery</strong> – The credential is sent back to the requester’s daemon, which stores it securely.</li><li><strong>Access unlocked</strong> – the daemon persists the membership outcome and informs the UI that the space is now available.</li><li><strong>Ongoing enforcement</strong> – peers verify and enforce membership across the implemented protected surfaces.</li></ol><p>Revocation can be implemented by expiring capabilities, publishing revocation events, or rotating space secrets. Regardless of the specifics, membership is always tied to the requesting peer’s ID, leveraging libp2p’s secure identity layer.<a href="https://docs.libp2p.io/concepts/security/security-considerations/" target="_blank" rel="noreferrer">^security</a></p><h3 id="current-implementation-snapshot" tabindex="-1">Current implementation snapshot <a class="header-anchor" href="#current-implementation-snapshot" aria-label="Permalink to &quot;Current implementation snapshot&quot;">​</a></h3><ul><li>Transport: libp2p request/response protocol <code>/soma/join/1</code> (see <code>soma-peer</code>).</li><li>Daemon: the in-process <code>DaemonHandle</code> (owned by the Tauri host&#39;s <code>desktop-daemon</code> crate) exposes <code>joinSpace</code>, then sends a JoinRequest over libp2p and surfaces decisions through the daemon event stream (relayed to the renderer as Tauri events).</li><li>Join decisions: <code>somad bot</code> ships a real join decider that approves requests (optionally attaching an issuer capability if the bot has been delegated) and persists decisions/memberships to the shared SQLx storage.</li><li>Bot operating modes: <ul><li><code>bot</code> mode (default): HTTP is read-only (<code>/info</code>, <code>/healthz</code>, <code>/metrics</code>); join decisions still flow over libp2p via the decider.</li><li><code>admin</code> mode: exposes admin-token-gated join control endpoints over HTTP for admin tooling; controllers still delegate to the decider/storage and never &quot;force-join&quot;.</li></ul></li><li>Auto-approval rules: the bot auto-approves only when it holds a valid issuer capability for the target space; otherwise join requests are recorded for manual approval. Manual approval surfaces exist in both the desktop daemon (via the in-process handle&#39;s <code>decideJoin</code>, surfaced to the renderer through <code>@soma/sdk</code>) and the bot&#39;s admin HTTP.</li><li>Owner delegation: the daemon exposes <code>issueIssuerCapability</code> on its in-process handle; the current daemon must own the space, and the signed delegation is persisted for audit/reuse.</li><li>Discovery: the daemon exposes <code>discoverSpaces</code>, but it currently returns only locally known/member spaces. Rendezvous-backed space discovery is still future work.</li><li>Ownership proof: new daemon-created spaces carry an owner-signed genesis artifact in storage.</li><li>Peer event pipeline: join decisions and failures are surfaced as <code>PeerEvent</code> and dispatched via the shared event dispatcher (see <code>docs/src/development/peer-events.md</code>).</li></ul><h3 id="current-limitation-pending-approval-is-transitional" tabindex="-1">Current limitation: pending approval is transitional <a class="header-anchor" href="#current-limitation-pending-approval-is-transitional" aria-label="Permalink to &quot;Current limitation: pending approval is transitional&quot;">​</a></h3><ul><li>The transport and storage model already support asynchronous join approval.</li><li>The proto does not yet expose a first-class <code>pending</code> decision state.</li><li>Today, manual-approval placeholders are still encoded with reject-shaped values and a <code>pending manual approval</code> reason.</li><li>Desktop UX should therefore describe join as &quot;request access and wait for approval&quot; rather than implying instant membership.</li></ul><p>See <code>docs/src/contracts/join-semantics.md</code> for the current workaround and the planned protocol cleanup.</p>',26)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
